# Deputy / Associate / Assistant General Counsel are not the legal chief.
_DEPUTY = re.compile(r"\b(?:deputy|associate|assistant)\b", re.IGNORECASE)


def _title_claim(claims: list[Claim]) -> Claim:
    """The claim whose wording is displayed: the newest one (a 2026 proxy beats a 2021
    newsroom post; an undated current leadership listing beats a 2020 announcement), then
    source priority, then the fuller wording ("..., Robinhood Financial" keeps its scope).
    Superseded wording stays in the facts."""

    def key(c: Claim) -> tuple:
        listing = not c.published_at and bool(_LISTING_PATH.search(urlsplit(c.doc.url).path))
        return (
            listing,
            _ordinal(c.published_at),
            -SOURCE_PRIORITY[c.doc.source_type],
            len(c.title),
            c.doc.url,
        )

    return max(claims, key=key)


def _blocked_host(c: Claim) -> bool:
    return str(c.doc.meta.get("direct_fetch", "")).startswith("blocked")


@dataclass
class ResolvedRole:
    title: str
    function: str
    seniority: str
    is_current: bool
    as_of: str | None
    confidence: str
    claims: list[Claim]
    note: str = ""


@dataclass
class ResolvedPerson:
    full_name: str
    claims: list[Claim]
    roles: list[ResolvedRole]
    confidence: str
    profile_url: str | None = None
    location: str | None = None
    location_claim: Claim | None = None
    bio: str | None = None
    bio_claim: Claim | None = None
    name_claim: Claim | None = None  # the claim the displayed name comes from

    @property
    def is_current(self) -> bool:
        return any(r.is_current for r in self.roles)


@dataclass
class Resolution:
    people: list[ResolvedPerson]
    review: dict[str, list[dict[str, Any]]]


def cluster_claims(claims: list[Claim], company_id: int = 0) -> list[list[Claim]]:
    """Group claims into people with compare_identity (SAME only), best evidence first."""
    clusters: list[list[Claim]] = []
    for claim in sorted(claims, key=_claim_sort_key):
        rec = NameRecord(company_id, claim.full_name, frozenset({claim.title_class.function}))
        for cluster in clusters:
            functions = frozenset(c.title_class.function for c in cluster)
            if compare_identity(rec, NameRecord(company_id, cluster[0].full_name, functions)) is (
                Identity.SAME
            ):
                cluster.append(claim)
                break
        else:
            clusters.append([claim])
    return clusters


def _role_keys(c: Claim, in_proxy: bool = False) -> list[tuple[str, str]]:
    """D4: General Counsel / Chief Legal is C-level only for a person the latest proxy lists
    as an executive officer; otherwise VP if the title has a VP token (D30), else Head."""
    if c.title_class.legal_chief and in_proxy:
        keys = [("c_level", "legal")]
    elif c.title_class.legal_chief:
        keys = [("vp" if c.title_class.seniority == "vp" else "head", "legal")]
    else:
        keys = [(c.title_class.seniority, c.title_class.function)]
    if c.title_class.also_founder:
        keys.append(("founder", "other"))
    return keys


def role_confidence(claims: list[Claim]) -> str:
    """high: an SEC filing, or 2+ sources incl. the company site. medium: the company site,
    or 2+ sources. low: a single search result."""
    urls = {c.doc.url for c in claims}
    types = {c.doc.source_type for c in claims}
    if "sec_filing" in types or (len(urls) >= 2 and "company_site" in types):
        return "high"
    if "company_site" in types or len(urls) >= 2:
        return "medium"
    return "low"


def _resolve_role(
    key: tuple[str, str],
    claims: list[Claim],
    proxy_date: str | None,
    proxy_keys: set[tuple[str, str]],
    today: date,
) -> ResolvedRole:
    seniority, function = key
    claims = sorted(claims, key=_claim_sort_key)
    current = [c for c in claims if c.status != "former"]
    former = [c for c in claims if c.status == "former"]
    newest_current = max((_ordinal(c.published_at) for c in current), default=-1)
    newest_former = max((_ordinal(c.published_at) for c in former), default=-1)
    note = ""
    retired_by_proxy = False
    # A 'former' statement wins unless a current claim is strictly newer (undated = oldest).
    is_current = bool(current) and (not former or newest_current > newest_former)
    if former and current:
        note = (
            f"sources disagree on whether this role is current: former per "
            f"{_cite(_newest(former))}; current per {_cite(_newest(current))}"
        )
    elif former:
        note = f"stated as former in {_cite(_newest(former))}"

    # D16 proxy rule: a dated C-level newsroom/search claim older than the latest proxy, for a
    # role the proxy doesn't list for this person, is not current. SEC claims are exempt.
    # Undated claims can't be shown to be older: they stay current and are listed for review
    # (the proxy lists only Section 16 officers, so e.g. a Chief People Officer may be absent).
    if (
        is_current
        and seniority == "c_level"
        and proxy_date is not None
        and key not in proxy_keys
        and not any(c.doc.source_type == "sec_filing" for c in current)
    ):
        if newest_current <= 0:
            note = (
                f"C-level title not in the {proxy_date} proxy; source is undated: "
                f"{_cite(current[0])}"
            )
        elif newest_current < _ordinal(proxy_date):
            is_current = False
            retired_by_proxy = True
            note = (
                f"not listed in the {proxy_date} proxy, which is newer than this claim; "
                f"last confirmed in {_cite(_newest(current))}"
            )

    supporting = current if is_current or retired_by_proxy else (former or claims)
    dated = [c.published_at for c in supporting if c.published_at]
    as_of = max(dated) if dated else None
    confidence = role_confidence(supporting)
    single = len({c.doc.url for c in supporting}) == 1
    if (
        is_current
        and single
        and as_of
        and (today - date.fromisoformat(as_of)).days > STALE_AFTER_DAYS
    ):
        confidence = "low"
        note = note or (
            f"single source, last dated {as_of} (older than 18 months), low confidence: "
            f"{_cite(supporting[0])}"
        )
    # D22: evidence re-anchored from the source (not the model's own quote) is low unless
    # another source corroborates the role. (Listed in review.reanchored either way, so the
    # stale note above keeps priority for the review lists.)
    if single and all(c.affiliation == "byline" for c in supporting):
        confidence = "low"
        note = note or (
            f"affiliation rests on a single author byline on the company's site: "
            f"{_cite(supporting[0])}"
        )
    if single and all(c.reanchored for c in supporting):
        confidence = "low"
        note = note or (
            f"evidence re-anchored by name and title in one block; single source: "
            f"{_cite(supporting[0])}"
        )
    title = _title_claim(supporting).title
    return ResolvedRole(title, function, seniority, is_current, as_of, confidence, claims, note)


def _title_key(title: str) -> str:
    """'CEO & Founder' and 'ceo and founder' are the same title."""
    return " ".join(re.sub(r"[^a-z0-9 ]", " ", title.lower().replace("&", " and ")).split())


def dedupe_roles(roles: list[ResolvedRole]) -> list[ResolvedRole]:
    """D29: one row per (normalized title, function) per person; sources are merged.

    "CEO & Founder" resolves to a C-level role and a founder role (D4/D23); shown as two
    identical rows. The merged row keeps the most senior seniority, is current if either
    was, and keeps every claim, the newest as_of, the best confidence, and both notes."""
    groups: dict[tuple[str, str], list[ResolvedRole]] = {}
    for r in roles:
        groups.setdefault((_title_key(r.title), r.function), []).append(r)
    out = []
    for group in groups.values():
        if len(group) == 1:
            out.append(group[0])
            continue
        lead = min(group, key=lambda r: (not r.is_current, _SENIORITY_RANK[r.seniority]))
        claims = list({id(c): c for r in group for c in r.claims}.values())
        notes = [r.note for r in group if r.note]
        seniorities = sorted({r.seniority for r in group}, key=_SENIORITY_RANK.__getitem__)
        if len(seniorities) > 1:
            notes.append(f"one row for: {', '.join(seniorities)}")
        out.append(
            ResolvedRole(
                lead.title,
                lead.function,
                lead.seniority,
                any(r.is_current for r in group),
                max((r.as_of for r in group if r.as_of), default=None),
                max((r.confidence for r in group), key=_CONFIDENCE_RANK.__getitem__),
                claims,
                "; ".join(dict.fromkeys(notes)),
            )
        )
    return out


_TITLE_STOP = frozenset({"and", "of", "the", "llc", "inc", "for", "at", "to", "a"})
OVERLAP_MIN = 0.6  # Jaccard similarity of title words for "the wording mostly overlaps"


def _title_words(title: str) -> frozenset[str]:
    t = _title_key(title)
    t = re.sub(r"\bvice president\b", "vp", t)

    r"^(?:independent |lead independent |non-executive )?(?:board )?"
    r"(?:director|board member|member of the board|chair(?:man|woman|person)?"
    r"(?: of the board)?)$"
)
# An advisor is not an operating leader, whatever the prefix ("Chief Economic Advisor").
_ADVISOR = re.compile(r"\badvis[eo]rs?\b")
_FORMER = re.compile(r"\b(?:former(?:ly)?|ex-|previously|retired|outgoing)\b")


@dataclass(frozen=True)
class TitleClass:
    seniority: str  # c_level | vp | head | founder
    function: str
    also_founder: bool = False  # e.g. "Co-founder & CEO": one c_level role plus a founder role
    legal_chief: bool = False  # General Counsel / Chief Legal Officer: see D4 in resolve.py


def _clean(title: str) -> str:
    t = title.lower().replace("’", "'").replace("–", "-").replace("—", "-")
    t = " ".join(re.sub(r"[^a-z0-9&,'/\- ]", " ", t).split())
    # Plurals from shared titles: "Co-Founders and Co-CEOs" -> "co-founder and co-ceo"
    return re.sub(r"\b(founder|ceo|cfo|cto|coo|officer)s\b", r"\1", t)


def function_for(title: str) -> str:
    t = _clean(title)
    for function, pattern in _FUNCTION_PATTERNS:
        if re.search(pattern, t):
            return function
    return "other"


def mentions_former(title: str) -> bool:
    """'Former CFO', 'ex-VP', 'retired'. ('Interim' is a current role.)"""
    return bool(_FORMER.search(_clean(title)))


def strip_company(title: str, company_name: str | None) -> str:
    """Drop "<Company> <Word>" qualifiers ("Robinhood Financial", "Robinhood UK") so a
    subsidiary's name doesn't decide the function ("Financial" is not finance)."""
    if not company_name:
        return title
    name = re.escape(_clean(company_name).split(" ")[0])
    return " ".join(re.sub(rf"\b{name}(?:\s+[a-z]+)?\b", " ", title).split())


_VP_TOKEN = re.compile(r"\b(?:vice president|vp|svp|evp|avp)\b")
# "President of Robinhood UK", "President, Robinhood Financial": a subsidiary president.
_QUALIFIED_PRESIDENT = re.compile(r"\bpresident\s*(?:,|of\b)")


def classify_title(title: str, company_name: str | None = None) -> TitleClass | None:
    """Seniority and function for an in-scope leadership title, or None if out of scope.

    C-level means the company's own C-suite. A title that also carries a VP token ("Vice
    President and Chief Information Security Officer") or a subsidiary presidency ("President
    of Robinhood UK") is VP-level. General Counsel / Chief Legal Officer is returned as
    C-level with legal_chief=True; resolve.py applies the proxy test (D4)."""
    full = _clean(title)
    if not full or _BOARD_ONLY.match(full) or _ADVISOR.search(full):
        return None
    t = strip_company(full, company_name) or full
    founder = bool(re.search(r"\b(?:co-?)?founder\b", t))
    words = set(re.findall(r"[a-z]+", t))

    acronyms = [a for a in _C_ACRONYMS if a in words]
    chief = re.search(r"\bchief\b.*\bofficer\b", t)
    president = (
        re.search(r"(?<!vice )\bpresident\b", t)
        and not re.search(r"\bvice\b", t)
        and not _QUALIFIED_PRESIDENT.search(full)
    )
    counsel = re.search(r"\bgeneral counsel\b", t)
    legal_chief = bool(counsel or re.search(r"\bchief legal\b", t) or "clo" in words)
    # A VP token makes the title VP-level, also when it names a C-suite or legal-chief role:
    # "VP and Chief Information Security Officer", "VP-Legal", "VP and Deputy General
    # Counsel", "SVP, General Counsel". resolve.py may still make a General Counsel C-level
    # when the latest proxy lists the person as an executive officer (D4).
    if _VP_TOKEN.search(t) and (chief or acronyms or counsel or function_for(t) == "legal"):
        function = "legal" if counsel else function_for(t.replace("chief executive officer", ""))
        return TitleClass("vp", function, also_founder=founder, legal_chief=legal_chief)
    if not (chief or acronyms or president or counsel) and _QUALIFIED_PRESIDENT.search(full):
        return TitleClass("vp", function_for(t.replace("president", "")), also_founder=founder)
    if chief or acronyms or president or counsel:
        if chief:
            # "Chair and Chief Executive Officer" -> other; "Chief Legal ... Officer" -> legal
            function = function_for(t.replace("chief executive officer", ""))
        elif acronyms:
            function = _C_ACRONYMS[acronyms[0]]
        elif counsel:
            function = "legal"
        else:
            function = function_for(t.replace("president", ""))
        return TitleClass("c_level", function, also_founder=founder, legal_chief=legal_chief)

    if re.search(r"\b(?:vice president|vp|svp|evp|avp)\b", t):
        return TitleClass("vp", function_for(t), also_founder=founder)
    if re.search(r"\bhead\b", t):
        return TitleClass("head", function_for(t), also_founder=founder)
    if founder:
        return TitleClass("founder", function_for(t.replace("founder", "")))
    return None
